<?php

declare(strict_types=1);

use Illuminate\Support\Facades\Config;
use Mahbub\SchemaTools\Support\Manifest;
use Mahbub\SchemaTools\Support\ManifestData;

const MANIFEST_HEADER = <<<'PHP'
    <?php

    declare(strict_types=1);

    /**
     * Source tables and views the code relies on, per database connection.
     *
     * Generated by `php artisan schema:detect`, which rewrites this file on every
     * run. Do not edit it: list what the detector cannot see as `sources` in
     * `schema-tools.php` instead.
     *
     * @return array<string, list<string>>
     */

    return 
    PHP;

it('keeps the generated manifest in the schema directory', function (): void {
    expect((new Manifest)->path())->toBe($this->workspace . '/source-tables.php');
})->group('need_review');

it('loads empty sections without sources or a generated file', function (): void {
    expect((new Manifest)->load())->toEqual(new ManifestData(manual: [], generated: []));
})->group('need_review');

it('loads the manual names from each connection sources and the generated file', function (): void {
    $this->manifestFile(generated: ['tcb' => ['Center']], manual: ['tcb' => ['Extra']]);

    expect((new Manifest)->load())->toEqual(new ManifestData(manual: ['tcb' => ['Extra']], generated: ['tcb' => ['Center']]));
})->group('need_review');

it('skips connections without sources', function (): void {
    Config::set('schema-tools.connections', [
        'legacy' => ['hand_maintained' => true],
        'sugar' => ['sources' => ['first' => 'contacts']],
    ]);

    expect((new Manifest)->load()->manual)->toBe(['sugar' => ['contacts']]);
})->group('need_review');

it('rejects connection settings that are :dataset', function (mixed $settings, string $message): void {
    Config::set('schema-tools.connections', ['sugar' => $settings]);

    expect(fn (): ManifestData => (new Manifest)->load())
        ->toThrow(InvalidArgumentException::class, $message);
})->group('need_review')->with([
    'not an array' => ['nonsense', '`connections.sugar` in schema-tools.php must be an array of settings.'],
    'sources that are not a list' => [['sources' => 'contacts'], '`connections.sugar.sources` in schema-tools.php must be a list of table and view names.'],
    'a source that is not a string' => [['sources' => ['contacts', 42]], '`connections.sugar.sources` in schema-tools.php must be a list of table and view names.'],
]);

it('rejects a generated manifest that returns :dataset', function (string $returned): void {
    $this->workspaceFile('source-tables.php', "<?php return {$returned};");

    expect(fn (): ManifestData => (new Manifest)->load())
        ->toThrow(UnexpectedValueException::class, '`' . $this->workspace . '/source-tables.php` must return a list of table and view names per connection; run `php artisan schema:detect` to rebuild it.');
})->group('need_review')->with([
    'no array' => ['1'],
    'names that are not a list' => ["['tcb' => 'Center']"],
    'a name that is not a string' => ["['tcb' => ['Center', 42]]"],
    'a connection without a name' => ["[['Center']]"],
]);

it('merges both sections per connection, manual first and without case-insensitive duplicates', function (): void {
    $manifest = new ManifestData(
        manual: ['tcb' => ['Extra', 'center']],
        generated: ['tcb' => ['Center', 'press'], 'sugar' => ['contacts']],
    );

    expect($manifest)
        ->all()->toBe(['tcb' => ['Extra', 'center', 'press'], 'sugar' => ['contacts']])
        ->names('tcb')->toBe(['Extra', 'center', 'press'])
        ->names('none')->toBe([]);
})->group('need_review');

it('writes only the generated names, replacing the whole file', function (): void {
    $this->workspaceFile('source-tables.php', "<?php\n\n// stale\nreturn ['tcb' => ['Gone']];\n");
    $manifest = new Manifest;

    $manifest->write(new ManifestData(
        manual: ['sugar' => ['bhea_orders_cstm']],
        generated: ['tcb' => ['Center', 'press'], 'tcbpermission' => ['MasterProduct']],
    ));

    expect((string) file_get_contents($manifest->path()))
        ->toBe(MANIFEST_HEADER . "[\n    'tcb' => [\n        'Center',\n        'press',\n    ],\n    'tcbpermission' => [\n        'MasterProduct',\n    ],\n];\n")
        ->and($manifest->load())->toEqual(new ManifestData(manual: [], generated: ['tcb' => ['Center', 'press'], 'tcbpermission' => ['MasterProduct']]));
})->group('need_review');

it('writes an empty manifest', function (): void {
    $manifest = new Manifest;

    $manifest->write(new ManifestData(manual: [], generated: []));

    expect((string) file_get_contents($manifest->path()))->toBe(MANIFEST_HEADER . "[];\n")
        ->and($manifest->load())->toEqual(new ManifestData(manual: [], generated: []));
})->group('need_review');
